import {useCallback} from 'react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteQueryKey} from '@github-ui/react-core/future/use-route-query-key'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import {useQueryClient} from '@github-ui/react-query'
import {businessPublicMonitoringRoute} from './public-monitoring-route'
import {PublicMonitoringPage} from '../components/PublicMonitoringPage'
import {PublicMonitoringSelfService} from '../components/PublicMonitoringSelfService'

export function BusinessRoute() {
  const payload = useRouteQuery(businessPublicMonitoringRoute, 'mainQuery').data
  const {slug} = useRouteParams(businessPublicMonitoringRoute)
  const queryClient = useQueryClient()
  const queryKey = useRouteQueryKey(businessPublicMonitoringRoute, 'mainQuery')

  const handleEnableSuccess = useCallback(async () => {
    if (queryKey) {
      await queryClient.invalidateQueries({queryKey})
    }
  }, [queryClient, queryKey])

  if (payload.selfServiceEligible) {
    return <PublicMonitoringSelfService enterpriseSlug={slug} onEnableSuccess={handleEnableSuccess} />
  }

  return <PublicMonitoringPage payload={payload} ownerType="business" name={slug} />
}
