import {Link, RelativeTime} from '@primer/react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLText} from '@github-ui/safe-html/VerifiedHTML'

export interface CommitFooterProps {
  commitOid: string
  commitUrl: string | null
  commitMessage?: SafeHTMLString
  commitCreatedAt?: string
  commitAuthorAvatarUrl?: string
}

export function CommitFooter({
  commitOid,
  commitUrl,
  commitMessage,
  commitCreatedAt,
  commitAuthorAvatarUrl,
}: CommitFooterProps) {
  return (
    <div className="border-top d-flex flex-items-center tmp-px-3 tmp-py-1">
      {commitAuthorAvatarUrl && <GitHubAvatar alt="" size={16} src={commitAuthorAvatarUrl} />}
      {commitUrl ? (
        <Link href={commitUrl} className="f6 tmp-ml-2">
          {commitMessage && <VerifiedHTMLText html={commitMessage} className="fgColor-default" />}
          <span className="text-mono tmp-ml-1">{commitOid.slice(0, 7)}</span>
        </Link>
      ) : (
        <>
          {commitMessage && <VerifiedHTMLText html={commitMessage} className="f6 tmp-ml-2 fgColor-muted" />}
          <span className="f6 text-mono tmp-ml-1">{commitOid.slice(0, 7)}</span>
        </>
      )}
      <div className="ml-auto tmp-mr-1">
        {commitCreatedAt && <RelativeTime className="f6" date={new Date(commitCreatedAt)} />}
      </div>
    </div>
  )
}
