import {Link} from '@primer/react'
import type {Icon} from '@primer/octicons-react'
import {IssueOpenedIcon, CommentDiscussionIcon, GitPullRequestIcon} from '@primer/octicons-react'
import {LocationContentType} from '../../types'
import styles from './LocationCard.module.css'

interface ContentLocationCardProps {
  contentType: string
  contentNumber?: number
  url: string | null
}

export function ContentLocationCard({contentType, contentNumber, url}: ContentLocationCardProps) {
  const {icon: Icon, label} = getContentTypeDisplay(contentType, contentNumber)

  return (
    <div className={`border rounded-2 tmp-mt-1 tmp-mb-2 overflow-hidden ${styles.locationCard}`}>
      <div className="d-flex flex-items-center gap-2 tmp-py-3 tmp-px-3">
        <Icon className="fgColor-muted" />
        {url ? (
          <Link href={url} className="f6">
            {label}
          </Link>
        ) : (
          <span className="f6 fgColor-muted">{label}</span>
        )}
      </div>
    </div>
  )
}

function getContentTypeDisplay(contentType: string, contentNumber?: number): {icon: Icon; label: string} {
  const suffix = contentNumber ? ` #${contentNumber}` : ''

  switch (contentType) {
    case LocationContentType.IssueTitle:
    case LocationContentType.IssueBody:
      return {icon: IssueOpenedIcon, label: `This secret was found in issue${suffix}`}
    case LocationContentType.IssueComment:
      return {icon: IssueOpenedIcon, label: `This secret was found in a comment on issue${suffix}`}
    case LocationContentType.DiscussionTitle:
    case LocationContentType.DiscussionBody:
      return {icon: CommentDiscussionIcon, label: `This secret was found in discussion${suffix}`}
    case LocationContentType.DiscussionComment:
      return {icon: CommentDiscussionIcon, label: `This secret was found in a comment on discussion${suffix}`}
    case LocationContentType.PullRequestTitle:
    case LocationContentType.PullRequestBody:
      return {icon: GitPullRequestIcon, label: `This secret was found in pull request${suffix}`}
    case LocationContentType.PullRequestComment:
      return {icon: GitPullRequestIcon, label: `This secret was found in a comment on pull request${suffix}`}
    case LocationContentType.PullRequestReview:
      return {icon: GitPullRequestIcon, label: `This secret was found in a review on pull request${suffix}`}
    case LocationContentType.PullRequestReviewComment:
      return {icon: GitPullRequestIcon, label: `This secret was found in a review comment on pull request${suffix}`}
    default:
      return {icon: IssueOpenedIcon, label: 'This secret was found in non-code content'}
  }
}
