import type {MouseEvent} from 'react'
import {Label, Link, Truncate, RelativeTime} from '@primer/react'

import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'

import {SECRET_CATEGORY_ICON, getSecretCategory} from '../secret-categories'
import type {PublicMonitoringAlert} from '../types'
import {attributionMethodLabel, getAttributionColorClasses} from '../types'
import styles from './AlertListItem.module.css'

const SECRET_PREVIEW_MAX_LENGTH = 40

function truncateSecret(rawSecret: string | null): string | null {
  if (!rawSecret) return null
  if (rawSecret.length <= SECRET_PREVIEW_MAX_LENGTH) return rawSecret
  return `${rawSecret.slice(0, SECRET_PREVIEW_MAX_LENGTH)}...`
}

interface AlertListItemProps {
  alert: PublicMonitoringAlert
  onClick?: (event: MouseEvent) => void
}

export function AlertListItem({alert, onClick}: AlertListItemProps) {
  const secretPreview = truncateSecret(alert.rawSecret)
  const leadingVisual = SECRET_CATEGORY_ICON[getSecretCategory(alert.slug)]
  const colorClasses = getAttributionColorClasses(alert.attributionMethod)

  return (
    <ListItem
      className="tmp-py-3"
      alignment="center"
      title={
        <ListItemTitle
          value={
            <>
              <span className="sr-only">Secret scanning alert: </span>
              {alert.secretTypeLabel}
            </>
          }
          onClick={onClick}
        >
          {secretPreview && (
            <span className="tmp-ml-2 tmp-px-1 bgColor-muted rounded-2 d-inline-flex">
              <Truncate title={secretPreview} maxWidth={280}>
                <span className={`f5 text-mono ${styles.secretPreview}`}>{secretPreview}</span>
              </Truncate>
            </span>
          )}
        </ListItemTitle>
      }
      metadata={
        <ListItemMetadata alignment="right">
          <Label variant="secondary" size="small" className={`${colorClasses} border-0 text-semibold`}>
            {attributionMethodLabel(alert)}
          </Label>
        </ListItemMetadata>
      }
    >
      <ListItemLeadingContent>
        <ListItemLeadingVisual
          {...leadingVisual}
          className={`${styles.icon} border tmp-p-1 rounded-2 fgColor-muted bgColor-muted flex-self-start`}
        />
      </ListItemLeadingContent>
      <ListItemMainContent>
        <ListItemDescription>
          <span>
            attributed <RelativeTime datetime={alert.createdAt} /> by {alert.committerIdentifier} in{' '}
            {/* repositoryName is NWO format from backend, safe to use directly in href */}
            <Link href={`/${alert.repositoryName}`} muted>
              {alert.repositoryName}
            </Link>
          </span>
        </ListItemDescription>
      </ListItemMainContent>
    </ListItem>
  )
}
