import type {MouseEvent} from 'react'
import {useRef, useState} from 'react'
import {ShieldIcon, AlertIcon} from '@primer/octicons-react'
import {Blankslate} from '@primer/react/experimental'
import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'

import type {PublicMonitoringAlert, PublicMonitoringPayload} from '../types'
import {AlertListItem} from './AlertListItem'
import {AlertDetailPanel} from './AlertDetailPanel'

interface AlertListProps {
  payload: PublicMonitoringPayload
  ownerName: string
}

export function AlertList({payload, ownerName}: AlertListProps) {
  const [selectedAlert, setSelectedAlert] = useState<PublicMonitoringAlert | null>(null)
  const returnFocusRef = useRef<HTMLElement | null>(null)

  function handleAlertClick(alert: PublicMonitoringAlert, event: MouseEvent) {
    if (event.currentTarget instanceof HTMLElement) {
      // The click target is an <a> without href (from ListItemTitle), which isn't
      // reliably focusable. Walk up to the nearest focusable ancestor (the <li>
      // with tabIndex=0) so SidePanel can restore focus on close.
      const focusable = event.currentTarget.closest<HTMLElement>('[tabindex], a[href], button')
      returnFocusRef.current = focusable ?? event.currentTarget
    }
    setSelectedAlert(alert)
  }

  if (payload.serviceError) {
    return (
      <Blankslate>
        <Blankslate.Visual>
          <AlertIcon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>Loading secrets failed</Blankslate.Heading>
        <Blankslate.Description>
          An error occurred while loading public monitoring alerts. Please try again later.
        </Blankslate.Description>
      </Blankslate>
    )
  }

  if (payload.alerts.length === 0) {
    return (
      <Blankslate>
        <Blankslate.Visual>
          <ShieldIcon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>No public monitoring alerts</Blankslate.Heading>
        <Blankslate.Description>No associated leaks have been detected on GitHub.com yet.</Blankslate.Description>
      </Blankslate>
    )
  }

  const count = payload.totalCount
  const title = `${count} associated leaks detected on GitHub.com`

  return (
    <>
      <div className="border rounded-2">
        <ListView title={title} titleHeaderTag="h2" totalCount={count} metadata={<ListViewMetadata title={title} />}>
          {payload.alerts.map(alert => (
            <AlertListItem key={alert.alertKey} alert={alert} onClick={(e: MouseEvent) => handleAlertClick(alert, e)} />
          ))}
        </ListView>
      </div>

      {selectedAlert && (
        <AlertDetailPanel
          alert={selectedAlert}
          onClose={() => setSelectedAlert(null)}
          returnFocusRef={returnFocusRef}
          ownerName={ownerName}
          verifiedDomains={payload.verifiedDomains}
        />
      )}
    </>
  )
}
