import {useState} from 'react'
import {Banner, Link} from '@primer/react'

const PREVIEW_COUNT = 5

interface VerifiedDomainBannerProps {
  verifiedDomains: string[]
}

export function VerifiedDomainBanner({verifiedDomains}: VerifiedDomainBannerProps) {
  const [expanded, setExpanded] = useState(false)

  if (verifiedDomains.length === 0) return null

  const visibleDomains =
    expanded || verifiedDomains.length <= PREVIEW_COUNT ? verifiedDomains : verifiedDomains.slice(0, PREVIEW_COUNT)
  const hiddenCount = verifiedDomains.length - visibleDomains.length

  return (
    <Banner
      variant="info"
      title="Verified domain attribution"
      hideTitle
      className="tmp-mb-3"
      data-testid="verified-domain-banner"
    >
      <div>
        You&apos;re seeing this alert because one of the committer&apos;s emails matches one of your verified domains:
      </div>
      <div className="d-flex flex-wrap flex-items-center gap-1 tmp-mt-1">
        {visibleDomains.map(domain => (
          <span
            key={domain}
            className="d-inline-block px-1 text-mono f6 border rounded-2 color-bg-default color-fg-default"
          >
            {domain}
          </span>
        ))}
        {hiddenCount > 0 && (
          <Link as="button" onClick={() => setExpanded(true)} className="f6">
            +{hiddenCount} more
          </Link>
        )}
      </div>
    </Banner>
  )
}
