import type {SafeHTMLString} from '@github-ui/safe-html'
import {
  issuePath,
  issueBodyPath,
  issueCommentPath,
  discussionPath,
  discussionBodyPath,
  discussionCommentPath,
  pullRequestTitlePath,
  pullRequestBodyPath,
  pullRequestCommentPath,
  pullRequestReviewPath,
  pullRequestReviewCommentPath,
} from '@github-ui/paths'

/**
 * Attribution method constants — match the user-friendly values returned by the API.
 * See: dotcom SecretScanning::PublicMonitoringAlert.display_attribution_method
 */
export const AttributionMethod = {
  Membership: 'member_activity',
  VerifiedDomain: 'verified_domain',
} as const

export const ATTRIBUTION_METHOD_LABELS: Record<string, string> = {
  [AttributionMethod.Membership]: 'Member activity',
  [AttributionMethod.VerifiedDomain]: 'Verified domain',
}

const DEFAULT_ATTRIBUTION_LABEL = 'Attribution unknown'
const ATTRIBUTION_COLORS: Record<string, string> = {
  [AttributionMethod.Membership]: 'bgColor-accent-muted fgColor-accent',
  [AttributionMethod.VerifiedDomain]: 'bgColor-success-muted fgColor-success',
}
const DEFAULT_ATTRIBUTION_COLOR = 'bgColor-accent-muted fgColor-accent'

// Maps legacy proto enum names to the canonical API values
const LEGACY_ATTRIBUTION_METHODS: Record<string, string> = {
  ATTRIBUTION_METHOD_MEMBERSHIP: AttributionMethod.Membership,
  ATTRIBUTION_METHOD_VERIFIED_DOMAIN: AttributionMethod.VerifiedDomain,
}

/**
 * Normalizes an attribution method value to the canonical form.
 * Handles both new API values and legacy proto enum names.
 */
export function normalizeAttributionMethod(value: string): string {
  return LEGACY_ATTRIBUTION_METHODS[value] ?? value
}

/**
 * Returns the human-readable attribution label for an alert.
 */
export function attributionMethodLabel(alert: PublicMonitoringAlert): string {
  return ATTRIBUTION_METHOD_LABELS[normalizeAttributionMethod(alert.attributionMethod)] ?? DEFAULT_ATTRIBUTION_LABEL
}

/**
 * Returns the shared attribution label color classes for an attribution method.
 */
export function getAttributionColorClasses(attributionMethod: string): string {
  return ATTRIBUTION_COLORS[normalizeAttributionMethod(attributionMethod)] ?? DEFAULT_ATTRIBUTION_COLOR
}

/**
 * Shared alert shape — fields common to both public monitoring and ACV.
 * When we reuse these components for ACV, adapters can map ACV data into this shape.
 */
export interface SecretAlertSummary {
  secretTypeLabel: string
  rawSecret: string | null
  createdAt: string
  /**
   * The repository name in NWO (name with owner) format, e.g. "owner/repo".
   * Safe to use directly in hrefs.
   */
  repositoryName: string
}

export interface PublicMonitoringAlert extends SecretAlertSummary {
  alertKey: string
  secretAuthorId: number
  slug: string
  label: string
  tokenTypeProvider: string
  validity: string
  resolution: string
  attributionMethod: string
  committerIdentifier: string
  committerEmail: string | null
  committerAvatarUrl: string | null
}

export interface PublicMonitoringPayload {
  alerts: PublicMonitoringAlert[]
  totalCount: number
  nextCursor: string | null
  previousCursor: string | null
  serviceError?: boolean
  /**
   * When true, the enterprise has the alert settings feature flag enabled but
   * has not yet opted in. The UI should render the self-service splash page
   * instead of the alert list.
   */
  selfServiceEligible?: boolean
  /**
   * Verified domains attributed to this enterprise.
   * Used to render an explanatory banner on alerts attributed via verified domain.
   * Mirrors the attribution scope on the backend (verified-only, business-owned + org-owned).
   */
  verifiedDomains: string[]
}

/**
 * Location content type constants — synced with proto enum values.
 * See: secret-scanning-proto ContentType enum.
 */
export const LocationContentType = {
  RepositoryBlob: 'REPOSITORY_BLOB',
  WikiBlob: 'WIKI_BLOB',
  IssueTitle: 'ISSUE_TITLE',
  IssueBody: 'ISSUE_BODY',
  IssueComment: 'ISSUE_COMMENT',
  DiscussionTitle: 'DISCUSSION_TITLE',
  DiscussionBody: 'DISCUSSION_BODY',
  DiscussionComment: 'DISCUSSION_COMMENT',
  PullRequestTitle: 'PULL_REQUEST_TITLE',
  PullRequestBody: 'PULL_REQUEST_BODY',
  PullRequestComment: 'PULL_REQUEST_COMMENT',
  PullRequestReview: 'PULL_REQUEST_TIMELINE_COMMENT',
  PullRequestReviewComment: 'PULL_REQUEST_REVIEW_COMMENT',
} as const

export type LocationContentType = (typeof LocationContentType)[keyof typeof LocationContentType]

export function isCodeLocation(contentType: string): boolean {
  return contentType === LocationContentType.RepositoryBlob || contentType === LocationContentType.WikiBlob
}

/**
 * Builds a URL to the issue, pull request, or discussion where the secret was found.
 * Uses @github-ui/paths for proper encoding and anchor fragments (e.g. #issuecomment-123).
 * Returns null if the content type doesn't map to a linkable resource or contentNumber is missing.
 */
export function getContentLocationUrl({
  owner,
  repo,
  contentType,
  contentNumber,
  contentId,
}: {
  owner?: string
  repo?: string
  contentType: string
  contentNumber?: number
  contentId?: number
}): string | null {
  if (!contentNumber) return null
  if (!owner || !repo) return null

  switch (contentType) {
    case LocationContentType.IssueTitle:
      return issuePath({owner, repo, issueNumber: contentNumber})
    case LocationContentType.IssueBody:
      return contentId
        ? issueBodyPath({owner, repo, issueNumber: contentNumber, contentId})
        : issuePath({owner, repo, issueNumber: contentNumber})
    case LocationContentType.IssueComment:
      return contentId
        ? issueCommentPath({owner, repo, issueNumber: contentNumber, contentId})
        : issuePath({owner, repo, issueNumber: contentNumber})
    case LocationContentType.PullRequestTitle:
      return pullRequestTitlePath({owner, repo, number: contentNumber})
    case LocationContentType.PullRequestBody:
      return contentId
        ? pullRequestBodyPath({owner, repo, number: contentNumber, contentId})
        : pullRequestTitlePath({owner, repo, number: contentNumber})
    case LocationContentType.PullRequestComment:
      return contentId
        ? pullRequestCommentPath({owner, repo, number: contentNumber, contentId})
        : pullRequestTitlePath({owner, repo, number: contentNumber})
    case LocationContentType.PullRequestReview:
      return contentId
        ? pullRequestReviewPath({owner, repo, number: contentNumber, contentId})
        : pullRequestTitlePath({owner, repo, number: contentNumber})
    case LocationContentType.PullRequestReviewComment:
      return contentId
        ? pullRequestReviewCommentPath({owner, repo, number: contentNumber, contentId})
        : pullRequestTitlePath({owner, repo, number: contentNumber})
    case LocationContentType.DiscussionTitle:
      return discussionPath({owner, repo, discussionNumber: contentNumber})
    case LocationContentType.DiscussionBody:
      return contentId
        ? discussionBodyPath({owner, repo, discussionNumber: contentNumber, contentId})
        : discussionPath({owner, repo, discussionNumber: contentNumber})
    case LocationContentType.DiscussionComment:
      return contentId
        ? discussionCommentPath({owner, repo, discussionNumber: contentNumber, contentId})
        : discussionPath({owner, repo, discussionNumber: contentNumber})
    default:
      return null
  }
}

export interface AlertLocation {
  path: string
  commitOid: string
  startLine: number
  endLine: number
  startColumn: number
  endColumn: number
  contentType: string
  contentNumber?: number
  contentId?: number
  createdAt: string | null
  foundInArchive: boolean
  commitMessage?: SafeHTMLString
  commitCreatedAt?: string
  commitAuthorAvatarUrl?: string
  blob?: {
    lines: SafeHTMLString[]
    language: string
    isTruncated: boolean
    isText: boolean
  }
}

export interface AlertDetailResponse {
  locations: AlertLocation[]
  totalLocationsCount: number
  locationsPerPage: number
  page: number
  repositoryOwner: string
  repositoryName: string
  commitAuthorEmail?: string | null
  committedAt?: string | null
}
