import type {ReactNode} from 'react'

import {Button, Details, Flash, Heading, Label, Link, Stack, useDetails} from '@primer/react'
import {ChevronDownIcon, ChevronUpIcon} from '@primer/octicons-react'

import {UpsellBanner} from '@github-ui/platform-patterns/UpsellBanner'

import upsellBannerLight from '../images/banner-light.png'
import upsellBannerDark from '../images/banner-dark.png'

import {useEnablePublicMonitoringMutation} from '../hooks/use-public-monitoring'
import styles from './PublicMonitoringSelfService.module.css'

const SECRET_PROTECTION_DOCS_URL =
  'https://docs.github.com/code-security/securing-your-organization/understanding-your-organizations-exposure-to-leaked-secrets/about-secret-protection'

export interface PublicMonitoringSelfServiceProps {
  /** Enterprise slug used to enable public monitoring. */
  enterpriseSlug: string
  /** Destination for the upsell banner "Learn more" link. */
  learnMoreUrl?: string
  /** Called after a successful enable, before navigation. Use to invalidate cached queries. */
  onEnableSuccess?: () => void | Promise<void>
}

export function PublicMonitoringSelfService({
  enterpriseSlug,
  learnMoreUrl = SECRET_PROTECTION_DOCS_URL,
  onEnableSuccess,
}: PublicMonitoringSelfServiceProps) {
  const {
    mutate: enableMonitoring,
    isPending: isEnabling,
    error,
  } = useEnablePublicMonitoringMutation({
    enterpriseSlug,
    onSuccess: onEnableSuccess,
  })

  return (
    <>
      <Stack direction="horizontal" gap="condensed" align="center">
        <Heading as="h1" className="f2">
          Public monitoring
        </Heading>
        <Label variant="success">Preview</Label>
      </Stack>

      {error && (
        <Flash variant="danger" role="alert" className="tmp-mt-2">
          {error.message}
        </Flash>
      )}

      <UpsellBanner
        className="tmp-mt-3"
        heading="Are your enterprise secrets leaking on GitHub.com?"
        description="GitHub monitors for secrets leaked across GitHub in real time. Public monitoring attributes publicly exposed secrets back to your enterprise, based on where your people commit."
        primaryActionText="Enable monitoring"
        primaryActionOnClick={enableMonitoring}
        primaryActionDisabled={isEnabling}
        secondaryActionText="Learn more"
        secondaryActionHref={learnMoreUrl}
        productShotLight={upsellBannerLight}
        productShotDark={upsellBannerDark}
        productShotAltText="Illustration showing list of public monitoring findings with example secrets and matched enterprise commits"
        contentLayout="large"
      />

      <Stack gap="condensed" className="tmp-mx-2 tmp-mt-5">
        <Heading as="h2" className="f3 tmp-mx-3">
          Frequently asked questions
        </Heading>
        <FaqItem question="What happens once I turn on public monitoring?">
          <p className="tmp-mb-0">
            GitHub will scan for public contributions associated to your enterprise. If a match is found, the alert will
            be surfaced in your public monitoring page. Anyone with the Enterprise Security Manager role will receive an
            email notification when findings are discovered in real time.
          </p>
        </FaqItem>
        <hr className="tmp-my-0 tmp-mx-3" />
        <FaqItem question="How are secrets attributed back to my enterprise?">
          <p className="tmp-mb-0">
            GitHub will attribute exposed secrets back to your enterprise based on enterprise membership. In the future,
            public monitoring will support additional heuristics like email matching for user and committer emails based
            on verified enterprise domains.
          </p>
        </FaqItem>
        <hr className="tmp-my-0 tmp-mx-3" />
        <FaqItem question="Who can use public monitoring?">
          <p className="tmp-mb-0">
            Public monitoring is available to all customers with an existing GitHub Secret Protection or GitHub Advanced
            Security plan at no additional cost.
          </p>
          <Link href={SECRET_PROTECTION_DOCS_URL} target="_blank" rel="noopener noreferrer">
            Learn more about GitHub Secret Protection
          </Link>
        </FaqItem>
      </Stack>
    </>
  )
}

function FaqItem({question, children}: {question: string; children: ReactNode}) {
  const {getDetailsProps} = useDetails({defaultOpen: true})
  const detailsProps = getDetailsProps()
  const trailingAction = detailsProps.open ? ChevronUpIcon : ChevronDownIcon

  return (
    <Details {...detailsProps} className={styles.FaqItem}>
      <Button
        block
        as="summary"
        size="large"
        className="f4"
        variant="invisible"
        alignContent="start"
        trailingAction={trailingAction}
      >
        {question}
      </Button>

      <Stack gap="condensed" className="tmp-pl-3 tmp-pr-6 tmp-pb-2 color-fg-muted">
        {children}
      </Stack>
    </Details>
  )
}
